/// <summary>
/// Coc extension for purchformletter_invoice
/// </summary>
[ExtensionOf(classStr(PurchFormLetter_Invoice))]
final class METPurchFormLetter_Invoice_Extension
{
}

Method.Source:
    /// <summary>
    /// extension of method to update the invoice date when multiple PO are selected to invoice
    /// </summary>
    /// <param name="_origPurchSubTableSet">
    ///    A set of <c>PurchId</c> values for creating records in the <c>_vendInvoiceInfoTable</c> table.
    /// </param>
    /// <param name="_newPurchLineSet">
    ///    A set of <c>RecId</c> values for creating records in the <c>VendInvoiceInfoLine</c> table.
    /// </param>
    /// <param name="_vendInvoiceInfoTable">
    ///    The default <c>VendInvoiceInfoTable</c> record in the <c>VendEditInvoice</c> form.
    /// </param>
    public void purchSelectLines(Set _origPurchSubTableSet, Set _newPurchLineSet, VendInvoiceInfoTable _vendInvoiceInfoTable)
    {
        next purchSelectLines(_origPurchSubTableSet, _newPurchLineSet, _vendInvoiceInfoTable);

        this.metUpdateParmTableInvoiceDate();
    }

    /// <summary>
    /// update the invoice date of the invoice
    /// </summary>
    private void metUpdateParmTableInvoiceDate()
    {
        VendPackingSlipJour     metVendPackingSlipJour;
        VendPackingSlipTrans    metVendPackingSlipTrans;
        VendInvoiceInfoSubLine  metVendInvoiceInfoSubLine;
        VendInvoiceInfoLine     metVendInvoiceInfoLine;
        VendInvoiceInfoTable    metVendInvoiceInfoTable = VendInvoiceInfoTable::findRecId(parmTable.RecId, true);
        
        if(VendParameters::find().METDefaultInvDate)
        {
            select firstonly DeliveryDate from metVendPackingSlipJour
                        order by DeliveryDate asc
                    exists join metVendPackingSlipTrans
                        where   metVendPackingSlipTrans.VendPackingSlipJour    == metVendPackingSlipJour.RecId
                    exists join metVendInvoiceInfoSubLine
                        where   metVendInvoiceInfoSubLine.JournalRefRecId      == metVendPackingSlipTrans.RecId &&
                                metVendInvoiceInfoSubLine.JournalRefTableId    == tableNum(VendPackingSlipTrans)
                    exists join metVendInvoiceInfoLine
                        where   metVendInvoiceInfoLine.RecId       == metVendInvoiceInfoSubLine.LineRefRecId &&
                                metVendInvoiceInfoLine.ParmId      == metVendInvoiceInfoTable.ParmId &&
                                metVendInvoiceInfoLine.TableRefId  == metVendInvoiceInfoTable.TableRefId;

            if(metVendPackingSlipJour && metVendPackingSlipJour.DeliveryDate != metVendInvoiceInfoTable.DocumentDate)
            {
                ttsbegin;
                metVendInvoiceInfoTable.DocumentDate = metVendPackingSlipJour.DeliveryDate;
                metVendInvoiceInfoTable.update();
                ttscommit;
            }
        }
    }
